gPB(){return"\u042d\u0442\u043e\u0442 \u0437\u043d\u0430\u043a \u0437\u0430\u043f\u0440\u0435\u0449\u0430\u0435\u0442 \u043f\u043e\u0432\u043e\u0440\u043e\u0442 \u043d\u0430\u043b\u0435\u0432\u043e?"},
gPA(){return"\u041d\u0435\u0442. \u041e\u043d \u0437\u0430\u043f\u0440\u0435\u0449\u0430\u0435\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u043e\u0432\u043e\u0440\u043e\u0442 \u043d\u0430\u043f\u0440\u0430\u0432\u043e \u043d\u0430 \u0431\u043b\u0438\u0436\u0430\u0439\u0448\u0435\u043c \u043f\u0435\u0440\u0435\u0441\u0435\u0447\u0435\u043d\u0438\u0438 \u043f\u0440\u043e\u0435\u0437\u0436\u0438\u0445 \u0447\u0430\u0441\u0442\u0435\u0439."},
gPD(){return u.m},
